using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class FinishCaveRestoreRubble {
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");int n=0;float max=0;foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.name=="Fallen cave stone")){var t=mf.transform;var size=mf.sharedMesh.bounds.size;t.rotation=Quaternion.Euler(0,t.eulerAngles.y,0);t.localScale=new(Mathf.Min(t.localScale.x,.65f/size.x),.16f/size.y,Mathf.Min(t.localScale.z,.8f/size.z));Physics.SyncTransforms();var hits=Physics.RaycastAll(t.position+Vector3.up*2,Vector3.down,35,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>h.distance).ToArray();if(hits.Length==0)throw new Exception("Missing rubble support");float min=mf.sharedMesh.vertices.Min(v=>t.TransformPoint(v).y);t.position+=Vector3.up*(hits[0].point.y-.035f-min);max=Mathf.Max(max,mf.sharedMesh.vertices.Max(v=>t.TransformPoint(v).y)-mf.sharedMesh.vertices.Min(v=>t.TransformPoint(v).y));n++;}EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());File.WriteAllText("Docs/CaveRestore/rubble.txt",$"{n} decorative ground stones; maximum true vertex height={max:F3}m; maximum footprint=.65x.8m; grounded .035m below support. Prior renderer-bounds cap retained tilted height; corrected using actual vertices and yaw-only rotation.");return File.ReadAllText("Docs/CaveRestore/rubble.txt");}
}
